CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value MEDIUMTEXT NOT NULL, updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE gateways (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone_number VARCHAR(20) NULL, operator_name VARCHAR(80) NULL, device_model VARCHAR(120) NULL, android_version VARCHAR(40) NULL, app_version VARCHAR(40) NULL, api_token_hash CHAR(64) NOT NULL UNIQUE, pairing_hash CHAR(64) NULL, pairing_expires DATETIME NULL, status ENUM('offline','online') NOT NULL DEFAULT 'offline', last_seen DATETIME NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE contacts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, phone VARCHAR(20) NOT NULL UNIQUE, display_name VARCHAR(120) NULL, consent_status ENUM('unknown','opted_in','opted_out') NOT NULL DEFAULT 'unknown', source VARCHAR(80) NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE contact_groups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE contact_group_members (group_id BIGINT UNSIGNED NOT NULL, contact_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(group_id,contact_id), FOREIGN KEY(group_id) REFERENCES contact_groups(id) ON DELETE CASCADE, FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, gateway_id BIGINT UNSIGNED NULL, status ENUM('draft','queued','running','paused','completed','cancelled') NOT NULL DEFAULT 'draft', test_mode TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, started_at DATETIME NULL, ended_at DATETIME NULL, FOREIGN KEY(gateway_id) REFERENCES gateways(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sms_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_uuid CHAR(36) NOT NULL UNIQUE, campaign_id BIGINT UNSIGNED NULL, gateway_id BIGINT UNSIGNED NULL, phone VARCHAR(20) NOT NULL, body TEXT NOT NULL, status ENUM('queued','processing','sent','delivered','failed','cancelled') NOT NULL DEFAULT 'queued', attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, idempotency_key VARCHAR(100) NOT NULL UNIQUE, error_text VARCHAR(500) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE SET NULL, FOREIGN KEY(gateway_id) REFERENCES gateways(id) ON DELETE SET NULL, INDEX(gateway_id,status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sms_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(24) NOT NULL, detail VARCHAR(500) NULL, created_at DATETIME NOT NULL, FOREIGN KEY(job_id) REFERENCES sms_jobs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE blocklist (phone VARCHAR(20) PRIMARY KEY, reason VARCHAR(180) NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE telegram_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(80) NOT NULL, result VARCHAR(24) NOT NULL, detail VARCHAR(500) NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, details TEXT NULL, ip VARCHAR(45) NULL, created_at DATETIME NOT NULL, INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE api_rate_limits (bucket_key CHAR(64) PRIMARY KEY, window_start DATETIME NOT NULL, hits INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
